import React from "react";
import { Link } from "react-router-dom";
import styled, { keyframes } from "styled-components";
import program1 from "../programs/program1";
import program2 from "../programs/program2";
import program3 from "../programs/program3";
import program4 from "../programs/program4";
import program5 from "../programs/program5";
import program6 from "../programs/program6";
import program7 from "../programs/program7";
import program8 from "../programs/program8";
import program9 from "../programs/program9";
import program11 from "../programs/program11";
import program14 from "../programs/program14";
import program15 from "../programs/program15";
import program16 from "../programs/program16";

const programs = [
  program1, program2, program3, program4, program5, program6,
  program7, program8, program9, program11, program14, program15, program16
];

// -------------------- ANIMATIONS --------------------
const fadeInUp = keyframes`
  0% { opacity: 0; transform: translateY(20px) scale(0.98); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
`;

const shine = keyframes`
  0% { transform: translateX(-100%); }
  100% { transform: translateX(200%); }
`;

// -------------------- STYLED COMPONENTS --------------------
const Container = styled.div`
  padding: 60px 20px;
  max-width: 1200px;
  margin: 0 auto;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "San Francisco";
  color: #e6eef8;
`;

const Header = styled.div`
  text-align: center;
  margin-bottom: 60px;

  h1 {
    font-size: 3rem;
    font-weight: 800;
    background: linear-gradient(90deg, #60a5fa, #34d399, #06b6d4);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    margin-bottom: 14px;
    letter-spacing: -0.5px;
  }

  p {
    color: #94a3b8;
    font-size: 1.1rem;
  }
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 28px;
`;

const Card = styled(Link)`
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(14px);
  padding: 28px 22px;
  border-radius: 20px;
  text-decoration: none;
  color: #e6eef8;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-shadow: 0 10px 30px rgba(0,0,0,0.25);
  transition: all 0.35s ease;
  animation: ${fadeInUp} 0.6s ease forwards;
  font-family: 'Fira Code', monospace;
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.08);

  &:hover {
    transform: translateY(-10px) scale(1.02);
    box-shadow: 0 16px 40px rgba(0,0,0,0.35);
    background: rgba(255, 255, 255, 0.07);
  }

  &::before {
    content: "";
    position: absolute;
    top: 0;
    left: -150%;
    width: 100%;
    height: 100%;
    background: linear-gradient(
      120deg,
      rgba(255, 255, 255, 0.2),
      transparent
    );
    transform: skewX(-20deg);
  }

  &:hover::before {
    animation: ${shine} 1.2s ease;
  }
`;

const Title = styled.div`
  font-weight: 700;
  font-size: 1.25rem;
  margin-bottom: 10px;
`;

const Small = styled.div`
  color: #cbd5e1;
  font-size: 0.9rem;
`;

const Footer = styled.div`
  margin-top: 100px;
  font-size: 0.9rem;
  color: #94a3b8;
  text-align: center;

  a {
    color: #60a5fa;
    text-decoration: none;
    font-weight: 600;

    &:hover {
      text-decoration: underline;
    }
  }
`;

// -------------------- COMPONENT --------------------
export default function Dashboard() {
  return (
    <Container>
      <Header>
        <h1>✨ Code Playground</h1>
        <p>Your C Lab programs, beautifully organized.</p>
      </Header>

      <Grid>
        {programs.map((p, idx) => (
          <Card
            key={p.id}
            to={`/program/${p.id}`}
            style={{ animationDelay: `${idx * 0.07}s` }}
          >
            <Title>{p.title}</Title>
            <Small>Program #{p.id}</Small>
          </Card>
        ))}
      </Grid>

      <Footer>
        Built with ❤️ by{" "}
        <a href="https://www.instagram.com/_zainn.27" target="_blank" rel="noreferrer">
          @_zainn.27
        </a>
      </Footer>
    </Container>
  );
}
